script:
test("count cap binds and rounds up instead of truncating", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 100, cartonWeightKg: 8 }), { pallets: 3, cartonsPerPallet: 48 });
});

test("weight cap binds instead of the carton count", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 90, cartonWeightKg: 25 }), { pallets: 3, cartonsPerPallet: 40 });
});

test("does not split a carton and does not use total weight", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 5, cartonWeightKg: 400 }), { pallets: 3, cartonsPerPallet: 2 });
});

test("exact multiple of the cap needs two pallets", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 96, cartonWeightKg: 8 }), { pallets: 2, cartonsPerPallet: 48 });
});

test("one carton over an exact multiple needs three pallets", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 97, cartonWeightKg: 8 }), { pallets: 3, cartonsPerPallet: 48 });
});

test("carton cap of 48 exactly fills one pallet", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 48, cartonWeightKg: 20 }), { pallets: 1, cartonsPerPallet: 48 });
});

test("one below the carton cap still needs one pallet", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 47, cartonWeightKg: 20 }), { pallets: 1, cartonsPerPallet: 48 });
});

test("one above the carton cap needs two pallets", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 49, cartonWeightKg: 20 }), { pallets: 2, cartonsPerPallet: 48 });
});

test("weight of 21 kg uses floor so the cap is 47", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 48, cartonWeightKg: 21 }), { pallets: 2, cartonsPerPallet: 47 });
});

test("weight exactly 1000 kg is allowed on one pallet", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 1, cartonWeightKg: 1000 }), { pallets: 1, cartonsPerPallet: 1 });
});

test("one kg above 1000 is too heavy for a pallet", function () {
  assert.throws(function () {
    code.palletsNeeded({ cartons: 1, cartonWeightKg: 1001 });
  }, /^carton too heavy for a pallet$/);
});

test("zero cartons returns zero pallets", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 0, cartonWeightKg: 8 }), { pallets: 0, cartonsPerPallet: 48 });
});

test("weight of zero kg is invalid", function () {
  assert.throws(function () {
    code.palletsNeeded({ cartons: 1, cartonWeightKg: 0 });
  }, /^invalid cartonWeightKg$/);
});

test("negative carton count is invalid", function () {
  assert.throws(function () {
    code.palletsNeeded({ cartons: -1, cartonWeightKg: 8 });
  }, /^invalid cartons$/);
});

test("non-whole carton count is invalid", function () {
  assert.throws(function () {
    code.palletsNeeded({ cartons: 1.5, cartonWeightKg: 8 });
  }, /^invalid cartons$/);
});

test("non-numeric weight string is invalid", function () {
  assert.throws(function () {
    code.palletsNeeded({ cartons: 1, cartonWeightKg: "8" });
  }, /^invalid cartonWeightKg$/);
});
